#include <stdio.h>
int main(void) {
    int n;
    scanf("%d", &n);
    long long f = 1;
    for (int i = 2; i <= n; i++) f *= i;
    printf("%lld\n", f);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);
    int m = a;
    if (b > m) m = b;
    if (c > m) m = c;
    printf("%d\n", m);
    return 0;
}

#include <stdio.h>
void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}
int main(void) {
    int x, y;
    scanf("%d %d", &x, &y);
    swap(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int n;
    scanf("%d", &n);
    int *a = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", a + i);
    int s = 0;
    for (int i = 0; i < n; i++) s += *(a + i);
    printf("%d\n", s);
    free(a);
    return 0;
}

#include <iostream>
using namespace std;
class Counter {
    int v = 0;
public:
    void inc() { v++; }
    int get() { return v; }
};
int main() {
    int n;
    cin >> n;
    Counter c;
    for (int i = 0; i < n; i++) c.inc();
    cout << c.get() << "\n";
    return 0;
}

#include <iostream>
#include <string>
using namespace std;
class Animal {
public:
    virtual string sound() const { return "..."; }
};
class Dog : public Animal {
public:
    string sound() const override { return "Woof"; }
};
int main() {
    string name;
    cin >> name;
    Dog d;
    cout << "Dog " << name << " says " << d.sound() << "\n";
    return 0;
}
